NEW_FILES = {'arrangement.py': '"""\narrangement.py  --  does every piece in a room have a visible reason to stand where it stands?\n==============================================================================================\nThe walker, walking cold run 9383, of deli_a03\'s stair landing: "layout of these tables doesn\'t seem to have a rhyme\nor reason" -- and, of the fix: "nuance and flavor, but not look like random assortment" (the factory\'s roadmap 300).\nA room reads as designed when a player can see why each thing is where it is; it reads as generated when they\ncannot. This measures that, piece by piece, so a furnishing rule can be held to a number rather than to a look.\n\nEVERY STANDING PIECE gets the first REASON that holds, tried in this order:\n\n  wall     its footprint comes within `WALL_REACH` of an edge of its room\'s bounds. Room bounds stand in for walls:\n           an open-plan edge with no wall counts as one, which over-credits a piece there.\n  seat     a chair (`SEAT_WORDS` in its name) within `SEAT_REACH`, box to box, of a standing piece that is not one.\n  aligned  it shares a centre line -- x or y within `ALIGN_TOL` -- with another piece of the same stem in the room,\n           lying the same way (its long side on the same axis): a row, a column, a grid.\n  centred  its centre is on one of the room\'s own centre lines, within `ALIGN_TOL`.\n  grouped  its box comes within `GROUP_GAP` of another standing piece\'s -- a stool at its counter -- or within\n           `PILE_GAP` of another piece of its own stem: a pile of cartons, a stack of crates.\n  loose    none of them: the random assortment.\n\nA STANDING PIECE is a volume whose foot is on its storey\'s floor (`level_design.stands_on_storey`), not hung\n(`level_design._hung`), visual, colliding, at least `MIN_HEIGHT` tall, its centre in a room of that storey (the\ninnermost: `level_design._room_for_point`). Its footprint is `size_x` by `size_y` as recorded, axis-aligned; a\npiece\'s own small turn (a chair\'s `rot_z` jitter) is not read. The stem is its name before `_r<crc>_` or `_<room>_`.\n\nBY PRODUCER, because an author\'s intent is not this tool\'s to judge: `seed` (`level_design._seeded_cover`), `furnish`\n(its ``_r<crc>_`` names), `authored` (everything else). The headline is the generated pieces, seed and furnish.\n\nMeasurements only: per room, the count by reason; over a set of specs, the totals by producer and the rooms holding\ntwo or more loose GENERATED pieces. No verdict.\n\n    python arrangement.py                       # the library\'s own specs, lf_ excepted\n    python arrangement.py --lf                   # Level Factory\'s composed lf_ specs\n    python arrangement.py --presets 2            # every preset at two seeds, built in memory\n    python arrangement.py --spec deli_a03        # one spec, room by room\n"""\nimport argparse\nimport collections\nimport glob\nimport json\nimport os\nimport re\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nif HERE not in sys.path:\n    sys.path.insert(0, HERE)\n\nimport level_design  # noqa: E402\n\nREASONS = ("wall", "seat", "aligned", "centred", "grouped", "loose")\nWALL_REACH = 0.5      # m from a footprint edge to its room\'s edge\nSEAT_REACH = 1.0      # m, box to box, from a chair to what it serves\nALIGN_TOL = 0.1       # m between two centre lines that read as one\nGROUP_GAP = 0.3       # m, box to box, between two pieces that read as one\nPILE_GAP = 1.0        # m, box to box, between two pieces of one stem that read as one pile\nMIN_HEIGHT = 0.3      # m: under this a piece is floor dressing, not furniture\nSEAT_WORDS = ("chair", "stool", "seat")\n_FURNISHED = re.compile(r"^(?P<stem>[a-z_]+?)_r[0-9a-f]{8}_\\d+(_\\d+)?$")\n\n\ndef stem(name, room_id):\n    """The piece\'s kind: before furnish\'s ``_r<crc>_<n>`` or the seeder\'s ``_<room>_<n>``."""\n    m = _FURNISHED.match(name)\n    if m:\n        return m.group("stem")\n    head = name.split("_%s_" % room_id)[0] if ("_%s_" % room_id) in name else name\n    return re.sub(r"(_\\d+)+$", "", head)\n\n\ndef standing(spec):\n    """``{room id: [(volume, stem, box)]}`` for every standing piece, by its innermost room on its storey."""\n    sh = float(spec.get("story_height") or 3.0)\n    out = collections.defaultdict(list)\n    for v in spec.get("volumes") or []:\n        if v.get("visual") is False or v.get("collision") == "none":\n            continue\n        h = float(v.get("size_z", 0) or 0)\n        if h < MIN_HEIGHT or "x" not in v or "y" not in v:\n            continue\n        z = float(v.get("z", 0) or 0)\n        story = round((z - h / 2.0) / sh)\n        if not level_design.stands_on_storey(z, h, story * sh, sh) or level_design._hung(v, story * sh):\n            continue\n        room = level_design._room_for_point(spec, float(v["x"]), float(v["y"]), story)\n        if room is None:\n            continue\n        ax, ay = float(v.get("size_x", 0)) / 2.0, float(v.get("size_y", 0)) / 2.0\n        box = (float(v["x"]) - ax, float(v["y"]) - ay, float(v["x"]) + ax, float(v["y"]) + ay)\n        out[room["id"]].append((v, stem(str(v.get("name", "")), room["id"]), box))\n    return out\n\n\ndef _gap(a, b):\n    """The box-to-box gap between two footprints, 0 when they touch or overlap."""\n    dx = max(0.0, max(a[0], b[0]) - min(a[2], b[2]))\n    dy = max(0.0, max(a[1], b[1]) - min(a[3], b[3]))\n    return (dx * dx + dy * dy) ** 0.5\n\n\ndef producer(v, room):\n    """seed, furnish or authored: who stood this piece."""\n    if level_design._seeded_cover(v, room):\n        return "seed"\n    return "furnish" if _FURNISHED.match(str(v.get("name", ""))) else "authored"\n\n\ndef reasons(room, pieces):\n    """``[(volume, reason)]`` for a room\'s standing pieces, each by the first reason that holds."""\n    x0, y0, x1, y1 = room["bounds"]\n    cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0\n    out = []\n    for i, (v, st, b) in enumerate(pieces):\n        px, py = float(v["x"]), float(v["y"])\n        long_x = float(v.get("size_x", 0)) >= float(v.get("size_y", 0))\n        others = [p for j, p in enumerate(pieces) if j != i]\n        if min(b[0] - x0, x1 - b[2], b[1] - y0, y1 - b[3]) <= WALL_REACH:\n            why = "wall"\n        elif any(w in st for w in SEAT_WORDS) and any(\n                _gap(b, ob) <= SEAT_REACH for ov, ost, ob in others if not any(w in ost for w in SEAT_WORDS)):\n            why = "seat"\n        elif any(ost == st and (float(ov.get("size_x", 0)) >= float(ov.get("size_y", 0))) == long_x and\n                 (abs(float(ov["x"]) - px) <= ALIGN_TOL or abs(float(ov["y"]) - py) <= ALIGN_TOL)\n                 for ov, ost, ob in others):\n            why = "aligned"\n        elif abs(px - cx) <= ALIGN_TOL or abs(py - cy) <= ALIGN_TOL:\n            why = "centred"\n        elif any(_gap(b, ob) <= (PILE_GAP if ost == st else GROUP_GAP) for ov, ost, ob in others):\n            why = "grouped"\n        else:\n            why = "loose"\n        out.append((v, why))\n    return out\n\n\ndef spec_census(spec):\n    """``{room id: Counter((producer, reason) -> pieces)}`` for one spec."""\n    rooms = {r["id"]: r for r in spec.get("rooms") or [] if r.get("bounds")}\n    return {rid: collections.Counter((producer(v, rooms[rid]), why) for v, why in reasons(rooms[rid], ps))\n            for rid, ps in standing(spec).items() if rid in rooms}\n\n\ndef generated(c):\n    """A room\'s counter by reason over its generated pieces alone (seed and furnish)."""\n    out = collections.Counter()\n    for (who, why), n in c.items():\n        if who != "authored":\n            out[why] += n\n    return out\n\n\ndef _report(name_to_spec, label, detail=False):\n    tot = collections.Counter()\n    by_who = collections.Counter()\n    loose_rooms = []\n    for name, spec in name_to_spec:\n        for rid, c in spec_census(spec).items():\n            g = generated(c)\n            tot.update(g)\n            by_who.update(c)\n            if g["loose"] >= 2:\n                loose_rooms.append((g["loose"], sum(g.values()), name, rid))\n            if detail:\n                print("  %-28s %s" % (rid, "  ".join("%s %d" % (k, g[k]) for k in REASONS if g[k])))\n    n = sum(tot.values())\n    print("%s: %d generated standing pieces; %s" % (label, n, ", ".join(\n        "%s %d (%.1f %%)" % (k, tot[k], 100.0 * tot[k] / max(1, n)) for k in REASONS)))\n    for who in ("seed", "furnish", "authored"):\n        m = sum(v for (w, _r), v in by_who.items() if w == who)\n        print("  %-8s %5d pieces, loose %5d (%.1f %%)" % (who, m, by_who[(who, "loose")],\n                                                         100.0 * by_who[(who, "loose")] / max(1, m)))\n    print("  rooms holding two or more loose generated pieces: %d" % len(loose_rooms))\n    for k, total, name, rid in sorted(loose_rooms, reverse=True)[:15]:\n        print("    %3d loose of %3d  %s / %s" % (k, total, name, rid))\n    return tot, loose_rooms\n\n\ndef _specs(lf, root=HERE):\n    for p in sorted(glob.glob(os.path.join(root, "specs", "*.json"))):\n        name = os.path.basename(p)[:-len(".json")]\n        if name.startswith("lf_") != lf:\n            continue\n        d = json.load(open(p, encoding="utf-8"))\n        if isinstance(d, dict) and d.get("rooms"):\n            yield name, d\n\n\ndef _presets(seeds):\n    import presets\n    for key in sorted(presets.REGISTRY):\n        for seed in range(seeds):\n            s = presets.make(key, name="%s_census_%d" % (key, seed), seed=seed)\n            yield "%s@%d" % (key, seed), (s if isinstance(s, dict) else s.to_dict())\n\n\ndef main(argv=None):\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--lf", action="store_true")\n    ap.add_argument("--presets", type=int, default=0)\n    ap.add_argument("--spec")\n    ap.add_argument("--dir", default=HERE, help="a Deli Counter checkout whose specs/ to read (default: this one)")\n    a = ap.parse_args(argv)\n    if a.spec:\n        d = json.load(open(os.path.join(a.dir, "specs", a.spec + ".json"), encoding="utf-8"))\n        _report([(a.spec, d)], a.spec, detail=True)\n    elif a.presets:\n        _report(list(_presets(a.presets)), "presets at %d seed(s)" % a.presets)\n    else:\n        specs = list(_specs(a.lf, a.dir))\n        if not specs:\n            # NOTHING READ IS NOT NOTHING LOOSE: Level Factory\'s lf_ specs are untracked, so a clone has none\n            print("NO SPECS: %s holds no %s spec with rooms" % (os.path.join(a.dir, "specs"), "lf_" if a.lf else "library"))\n            return 1\n        _report(specs, "lf_ specs" if a.lf else "library")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'test_arrangement.py': '"""The arrangement census reads a room the way a player does (0.264.0).\n\n`arrangement.py` gives every standing piece the first visible reason it has to stand where it stands -- wall, seat,\naligned, centred, grouped -- or calls it loose. These are its controls: rooms built so the right answer is known, so\nan instrument that cannot tell a row from a scatter fails here rather than reporting a number nobody can trust.\n"""\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport arrangement  # noqa: E402\n\n\ndef _room(**kw):\n    s = {"name": "t", "story_height": 3.0, "rooms": [{"id": "office", "story": 0, "bounds": [0.0, 0.0, 12.0, 8.0]}],\n         "volumes": []}\n    s.update(kw)\n    return s\n\n\ndef _v(name, x, y, sx=1.0, sy=0.6, h=0.75):\n    return {"name": name, "x": x, "y": y, "z": h / 2.0, "size_x": sx, "size_y": sy, "size_z": h,\n            "collision": "convex"}\n\n\ndef _why(spec):\n    room = spec["rooms"][0]\n    return {v["name"]: why for v, why in arrangement.reasons(room, arrangement.standing(spec)["office"])}\n\n\ndef test_each_reason_is_read_as_built():\n    s = _room(volumes=[\n        _v("shelf_run_r00000001_1", 6.0, 0.4, 2.6, 0.6, 1.7),                 # against the south wall\n        _v("desk_r00000001_2", 3.0, 3.0), _v("desk_r00000001_3", 6.0, 3.0), _v("desk_r00000001_4", 9.0, 3.0),\n        _v("chair_set_r00000001_2_1", 3.0, 2.2, 0.5, 0.5, 0.9),                # at its desk\n        _v("crate_stack_office_0", 6.0, 4.0, 1.1, 1.1, 0.95),                  # on the room\'s centre line x = 6\n        _v("cartons_r00000001_5", 2.0, 6.0, 0.6, 0.6, 0.5), _v("cartons_r00000001_6", 2.9, 6.25, 0.5, 0.5, 0.4),\n        _v("planter_box_office_1", 8.7, 5.9, 1.4, 0.7, 0.9),                   # nothing\n    ])\n    got = _why(s)\n    assert got["shelf_run_r00000001_1"] == "wall"\n    assert {got["desk_r00000001_%d" % k] for k in (2, 3, 4)} == {"aligned"}\n    assert got["chair_set_r00000001_2_1"] == "seat"\n    assert got["crate_stack_office_0"] == "centred"\n    assert got["cartons_r00000001_5"] == got["cartons_r00000001_6"] == "grouped"\n    assert got["planter_box_office_1"] == "loose"\n\n\ndef test_a_scatter_reads_loose_and_its_row_does_not():\n    """The same three desks, scattered and turned, then in a row: the census tells them apart."""\n    scatter = _room(volumes=[_v("desk_r00000001_1", 3.0, 3.1), _v("desk_r00000001_2", 6.4, 5.2, 0.6, 1.0),\n                             _v("desk_r00000001_3", 9.2, 3.7)])\n    row = _room(volumes=[_v("desk_r00000001_1", 3.0, 3.1), _v("desk_r00000001_2", 6.4, 3.1),\n                         _v("desk_r00000001_3", 9.2, 3.1)])\n    assert set(_why(scatter).values()) == {"loose"}\n    assert set(_why(row).values()) == {"aligned"}\n\n\ndef test_two_aligned_pieces_turned_differently_are_not_a_row():\n    s = _room(volumes=[_v("table_work_r00000001_1", 3.0, 3.1, 1.2, 0.7), _v("table_work_r00000001_2", 3.0, 5.4, 0.7,\n                                                                              1.2)])\n    assert set(_why(s).values()) == {"loose"}\n\n\ndef test_hung_and_tiny_pieces_are_not_furniture():\n    sign = dict(_v("sign_r00000001_1", 4.0, 4.0, 1.0, 0.1, 0.5), collision="none", z=2.5)\n    s = _room(volumes=[sign, _v("bottle_r00000001_2", 4.0, 4.0, 0.1, 0.1, 0.2)])\n    assert arrangement.standing(s) == {}\n\n\ndef test_the_producers_are_told_apart():\n    room = {"id": "office", "bounds": [0, 0, 12, 8]}\n    assert arrangement.producer({"name": "desk_r0badf00d_3"}, room) == "furnish"\n    assert arrangement.producer({"name": "crate_stack_office_2"}, room) == "seed"\n    assert arrangement.producer({"name": "kitchen_prep_table"}, room) == "authored"\n', 'migrate_seed_lines.py': '"""\nmigrate_seed_lines.py  --  a room\'s seeded pieces stand in one line (0.264.0)\n=============================================================================\nOne-shot, idempotent migration over the library, specs/*.json, Level\nFactory\'s lf_ specs excepted as `layout_lint --all` excepts them. The seeder\nnow lays a room\'s pieces in one line (`level_design._line_up`); this lays the\nones the library already stores the same way. The walker, walking cold run\n9383, of deli_a03\'s stair landing: "layout of these tables doesn\'t seem to\nhave a rhyme or reason".\n\nONLY WHAT IS STORED, NEVER A RE-SEED. Replayed on the library, today\'s\n`seed_cover` gives back its stored pieces in 7 of 128 specs and places 1,419\npieces where 75 are stored -- the rules for whether a room is seeded moved\nafter these specs were seeded. Re-seeding would change the cover of nearly\nevery room in the library; this changes where the stored pieces stand and\nnothing else: the same pieces, kinds, heights and rooms.\n\nASKED AS THE SEEDER ASKS IT, BEFORE FURNISH (`migrate_seed_corridor`\'s rule):\neach spec is read without the volumes furnish wrote, and refurnished after\n(`migrate_furnish_recipes.migrate`) when anything moved, so it stays a fixed\npoint of furnish. A room no line fits keeps its pieces, and is named.\n\n    python migrate_seed_lines.py            # write specs/\n    python migrate_seed_lines.py --check    # report only\n"""\nimport collections\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport layout_lint               # noqa: E402\nimport level_design              # noqa: E402\nimport migrate_furnish_recipes   # noqa: E402\nimport migrate_seed_corridor     # noqa: E402\n\n\ndef _order(v):\n    """The seeder\'s order: its shelter piece first, then by the index it drew."""\n    name = v["name"]\n    return -1 if name.endswith("_shelter") else int(name.rsplit("_", 1)[1])\n\n\ndef rooms_seeded(view):\n    """``[(room, [pieces in the seeder\'s order])]`` for every room storing a seeded piece: a lone one\n    stands on the room\'s line too (0.264.0)."""\n    by_room = collections.OrderedDict()\n    for v in view.get("volumes") or []:\n        story = layout_lint.piece_story(view, v)\n        if story is None:\n            continue\n        room = level_design._room_for_point(view, float(v["x"]), float(v["y"]), story)\n        if level_design._seeded_cover(v, room):\n            by_room.setdefault(room["id"], (room, []))[1].append(v)\n    return [(room, sorted(vs, key=_order)) for room, vs in by_room.values()]\n\n\ndef migrate(d):\n    """Line up every room\'s stored seeded pieces, then refurnish, in place.\n    Returns ([lined room ids], [room ids no line fits])."""\n    view = migrate_seed_corridor._view(d)\n    building = level_design.club_building_id(d)\n    lined, kept = [], []\n    for room, pieces in rooms_seeded(view):\n        before = [(v["x"], v["y"], v["size_x"], v["size_y"]) for v in pieces]\n        # THE ROUTES THE ROOM HAS WITHOUT THESE PIECES (0.264.0), as `seed_cover`\n        # asks them before it stands any: asked with them standing, the routes\n        # bent round where they stood, and this migration\'s first draft lined\n        # pawn_shop_a01\'s two crates onto the safe room\'s true route\n        ids = {id(v) for v in pieces}\n        bare = dict(view, volumes=[v for v in view["volumes"] if id(v) not in ids])\n        routes = (level_design.protected_routes(level_design.unfurnished(bare), room)\n                  if level_design.reserves_routes(view, room, building) else [])\n        if not level_design._line_up(view, room, pieces, routes):\n            kept.append(room["id"])\n        elif [(v["x"], v["y"], v["size_x"], v["size_y"]) for v in pieces] != before:\n            lined.append(room["id"])\n    if lined:\n        migrate_furnish_recipes.migrate(d)\n    return lined, kept\n\n\ndef main():\n    check = "--check" in sys.argv\n    n_lined = n_kept = n_specs = 0\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        d = json.load(io.open(p, encoding="utf-8"))\n        if not d.get("rooms"):\n            continue\n        before = json.dumps(d, sort_keys=True)\n        lined, kept = migrate(d)\n        if not lined and not kept:\n            continue\n        n_specs += 1\n        print("%-36s lined %s%s" % (os.path.basename(p)[:-len(".json")], ", ".join(lined) or "-",\n                                    ("; NO LINE FITS, KEPT: %s" % ", ".join(kept)) if kept else ""))\n        n_lined += len(lined)\n        n_kept += len(kept)\n        if not check and json.dumps(d, sort_keys=True) != before:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("%d spec(s): %d room(s) lined, %d kept%s" % (\n        n_specs, n_lined, n_kept, " -- check only, nothing written" if check else ""))\n\n\nif __name__ == "__main__":\n    main()\n', 'test_seed_lines.py': '"""A room\'s seeded pieces stand in one line, or in rows where one line cannot (0.264.0).\n\nThe walker, walking cold run 9383, of deli_a03\'s stair landing: "layout of these tables doesn\'t seem to have a rhyme\nor reason" (the factory\'s `docs/findings/walk_2026-10-23_deli/`, finding 3; roadmap 300). `seed_cover` stood a room\'s\npieces where a shuffled, jittered grid\'s first fits fell, each turned by a coin flip. `_line_up` stands the same\npieces evenly along one straight line, long sides along it; a room no line fits keeps them where they were.\n\nTHE TEST THAT MATTERS IS `test_the_library_s_seeded_rooms_stand_in_lines`.\n"""\nimport copy\nimport glob\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport agent_contract        # noqa: E402\nimport level_design          # noqa: E402\nimport migrate_seed_lines    # noqa: E402\nimport migrate_seed_corridor  # noqa: E402\n\n#: Library rooms storing seeded pieces that stand in no lattice, kept where they stood (0.264.0\'s migration, the\n#: factory\'s `patches/dc_seed_lines/migrate.out.txt`): the two safe rooms too tight for one clear of the room\'s own\n#: route -- night_pawn\'s, beside the tall crate the shelter pass stood there, and pawn_shop_a01\'s, whose crates stood\n#: on that route at 0.263.0 already.\nKEPT = {("night_pawn", "safe_room"), ("pawn_shop_a01", "safe_room")}\nLINED = 35\n\n\ndef _spec():\n    """A bare 20 x 10 m combat room with nothing in it."""\n    return {"name": "t", "footprint_x": 20.0, "footprint_y": 10.0, "story_height": 3.0, "stories": 1,\n            "wall_thick": 0.3, "slab_holes": [], "stairs": [], "seed": 7,\n            "rooms": [{"id": "lobby", "story": 0, "bounds": [-10.0, -5.0, 10.0, 5.0],\n                       "role": "public_entry", "combat_range": "medium"}],\n            "volumes": [], "partitions": [], "ext_walls": [], "markers": []}\n\n\ndef _in_a_lattice(pieces):\n    """Rows along one axis, the rows evenly spaced, every piece\'s long side along its row, and every row on the\n    longest row\'s stations (a short row centred under them): one line is a lattice of one row, pieces abreast a\n    lattice of one column (0.264.0)."""\n    for along, across, key, lon in (("x", "y", "size_x", "size_y"), ("y", "x", "size_y", "size_x")):\n        if not all(v[key] >= v[lon] for v in pieces):\n            continue\n        rows = {}\n        for v in pieces:\n            rows.setdefault(round(v[across], 2), []).append(round(v[along], 2))\n        cs = sorted(rows)\n        pitches = [b - a for a, b in zip(cs, cs[1:])]\n        if pitches and max(pitches) - min(pitches) > 0.02:\n            continue\n        full = sorted(max(rows.values(), key=len))\n        step = (full[-1] - full[0]) / (len(full) - 1) if len(full) > 1 else 0.0\n        if len(full) > 2 and max(abs(b - a - step) for a, b in zip(full, full[1:])) > 0.02:\n            continue\n        ok = True\n        for row in rows.values():\n            want = [full[0] + (j + (len(full) - len(row)) / 2.0) * step for j in range(len(row))]\n            if len(row) == 1 and len(full) > 1 and len(rows) > 1:\n                want = [(full[0] + full[-1]) / 2.0]\n            if any(abs(a - b) > 0.02 for a, b in zip(sorted(row), want)):\n                ok = False\n        if ok:\n            return True\n    return False\n\n\ndef _in_a_line(pieces):\n    return _in_a_lattice(pieces) and (len({round(v["x"], 2) for v in pieces}) == 1 or\n                                      len({round(v["y"], 2) for v in pieces}) == 1)\n\n\ndef test_a_bare_room_s_pieces_are_seeded_in_a_line():\n    s = _spec()\n    assert level_design.seed_cover(s) >= 2\n    room = s["rooms"][0]\n    mine = [v for v in s["volumes"] if level_design._seeded_cover(v, room)]\n    assert len(mine) >= 2 and _in_a_line(mine), [(v["name"], v["x"], v["y"]) for v in mine]\n\n\ndef test_line_up_moves_the_same_pieces_and_nothing_else():\n    s = _spec()\n    room = s["rooms"][0]\n    pieces = [{"name": "crate_stack_lobby_%d" % k, "x": -7.0 + 5 * k, "y": (-1) ** k * 2.0, "z": 0.475,\n               "size_x": 1.1, "size_y": 1.1, "size_z": 0.95, "collision": "convex"} for k in range(3)]\n    s["volumes"] = copy.deepcopy(pieces)\n    assert level_design._line_up(s, room, s["volumes"])\n    assert _in_a_line(s["volumes"])\n    # a body passes between any two of them: the gap is the contract\'s corridor, not the centres\' spread\n    cw = agent_contract.min_corridor_width()\n    for a, b in zip(s["volumes"], s["volumes"][1:]):\n        gap = max(abs(a["x"] - b["x"]) - (a["size_x"] + b["size_x"]) / 2.0,\n                  abs(a["y"] - b["y"]) - (a["size_y"] + b["size_y"]) / 2.0)\n        assert gap >= cw - 1e-6, (a["name"], b["name"], gap)\n    for a, b in zip(pieces, s["volumes"]):\n        assert {k: a[k] for k in a if k not in ("x", "y", "size_x", "size_y")} == \\\n            {k: b[k] for k in b if k not in ("x", "y", "size_x", "size_y")}\n\n\ndef test_where_one_line_cannot_two_rows_do():\n    """Four pieces that want 10.5 m in one line, in a room 9 m long: two rows of two, a body passing every side of\n    each, every piece lying the same way (deli_a03\'s landing in small)."""\n    s = _spec()\n    s["rooms"][0]["bounds"] = [-4.5, -5.0, 4.5, 5.0]\n    s["footprint_x"], s["footprint_y"] = 9.0, 10.0\n    room = s["rooms"][0]\n    s["volumes"] = [{"name": "%s_lobby_%d" % (stem, k), "x": -2.0 + k, "y": (-1) ** k * 1.5, "z": 0.5, "size_x": sx,\n                     "size_y": sy, "size_z": 1.0, "collision": "convex"}\n                    for k, (stem, sx, sy) in enumerate((("counter_island", 2.2, 0.8), ("planter_box", 1.4, 0.7),\n                                                        ("counter_island", 0.8, 2.2), ("planter_box", 0.7, 1.4)))]\n    assert level_design._line_up(s, room, s["volumes"])\n    assert _in_a_lattice(s["volumes"]) and not _in_a_line(s["volumes"])\n    import migrate_seed_corridor\n    assert migrate_seed_corridor.failing(s) == []\n\n\ndef test_a_room_no_line_fits_keeps_its_pieces():\n    s = _spec()\n    s["rooms"][0]["bounds"] = [-2.0, -2.0, 2.0, 2.0]          # 4 x 4 m: no 2.2 m spread clear of its walls\n    s["footprint_x"] = s["footprint_y"] = 4.0\n    pieces = [{"name": "crate_stack_lobby_%d" % k, "x": 0.5 * k, "y": 0.0, "z": 0.475, "size_x": 1.1,\n               "size_y": 1.1, "size_z": 0.95, "collision": "convex"} for k in range(2)]\n    s["volumes"] = copy.deepcopy(pieces)\n    assert not level_design._line_up(s, s["rooms"][0], s["volumes"])\n    assert s["volumes"] == pieces\n\n\ndef test_the_library_s_seeded_rooms_stand_in_lines():\n    """Every library room storing a seeded piece stands it on a lattice -- a lone one on the room\'s line, two or more\n    in a line or rows -- but the one named in KEPT; and the library is a fixed point of the migration."""\n    lined, kept = set(), set()\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        name = os.path.basename(p)[:-5]\n        if name.startswith("lf_"):\n            continue\n        d = json.load(open(p, encoding="utf-8"))\n        if not d.get("rooms"):\n            continue\n        for room, pieces in migrate_seed_lines.rooms_seeded(migrate_seed_corridor._view(d)):\n            (lined if _in_a_lattice(pieces) else kept).add((name, room["id"]))\n        once = copy.deepcopy(d)\n        moved, _kept = migrate_seed_lines.migrate(once)\n        assert not moved and once == d, name\n    assert kept == KEPT, sorted(kept ^ KEPT)\n    assert len(lined) == LINED, sorted(lined)\n'}
CHANGELOG = '## [0.264.0] - a room\'s seeded pieces stand on a lattice, and a census of what has a reason to stand where it stands\n\n**The walker\'s walk of cold run 9383** (the factory\'s `docs/findings/walk_2026-10-23_deli/`, finding 3; roadmap 300),\nof deli_a03\'s stair landing: "layout of these tables doesn\'t seem to have a rhyme or reason" -- and of the fix: "do\nthe full correct fix, allowing us to have nuance and flavor, but not look like random assortment". `seed_cover` stood\na room\'s pieces where a shuffled, jittered grid\'s first fits fell, each turned by a coin flip.\n\n### Added\n- **`arrangement.py`**: every standing piece in a room gets the first visible reason it has to stand there -- `wall`,\n  `seat`, `aligned` (a row or grid of its own kind, lying the same way), `centred`, `grouped` (a pile, a stool at its\n  counter) -- or `loose`, the random assortment; by producer (seed, furnish, authored), over the library, Level\n  Factory\'s `lf_` specs (`--dir`, as they are untracked) or every preset built in memory (`--presets N`).\n  Measurements only; an empty population fails rather than reporting zeros. Its controls, `test_arrangement.py`.\n- **`_line_up(spec, room, pieces, routes=())`**: the same pieces on a LATTICE, in place -- one row first, then two, up\n  to `_SEED_LINE_ROWS` (3), a body\'s corridor between rows, every row on the same stations along it (a short last row\n  centred), ONE KIND A ROW (desks in a row and their cabinets behind, not alternating), long sides along the rows; the\n  rows\' position across the room every `_SEED_LINE_CROSS` (0.5 m), sampled every `_SEED_LINE_STEP` (0.2 m), the room\'s\n  long axis first, then the lattice\'s middle nearest the room\'s, the first clear on every row winning. Each piece is\n  cleared as `seed_cover` clears one, by its own footprint, the pieces already stood among what it clears, and off\n  the room\'s reserved routes. A lone piece stands on the room\'s line too. A room no lattice fits keeps its pieces.\n  `seed_cover` lays a room\'s pieces and then `_line_up`s them.\n- **`_seed_clear(..., size=None)`**: a piece\'s own footprint for every box rule -- off another volume, a stair\'s\n  reserve, a hole, a vault leaf, the body\'s corridor -- when it stands the way it is asked; the radius rules still ask\n  `half`. A counter 0.8 m deep was cleared as if it were 2.2 m deep. `migrate_seed_corridor.failing` and\n  `test_seed_corridor` ask a stored piece by its footprint the same way.\n- **`migrate_seed_lines.py`**: lines up the pieces the library stores, never re-seeding (replayed, today\'s seeder gives\n  back its stored pieces in 7 of 128 specs and would place 1,419 where 75 stand), the routes asked without the\n  room\'s own pieces as `seed_cover` asks them; then refurnishes.\n\n### Measured\n- **The census, 0.263.0 against this** (the factory\'s `patches/dc_seed_lines/arrangement_*.out.txt`): every preset at\n  two seeds, built in memory -- seeded pieces loose 95.4 % -> 13.8 %, every generated piece 25.7 % -> 13.1 %, rooms\n  holding two or more loose generated pieces 145 -> 88. The library -- seeded pieces loose 71.8 % -> 3.8 %, every\n  generated piece 14.7 % -> 14.1 %. Level Factory\'s `lf_` mission shells, built from presets, read 28.6 % loose\n  before, seeded cover 72.5 % of 3,092 pieces: the next ones are built by this seeder.\n- **The library, laid out, refurnished and sheltered**: 35 of the 37 rooms storing seeded pieces stand them on a\n  lattice -- deli_a03\'s landing and its four twins two rows of two, a row of counters and a row of planters; the\n  bank offices a row of desks and their cabinets behind -- and 2 keep theirs: night_pawn\'s and pawn_shop_a01\'s safe\n  rooms, too tight for one clear of their own routes (pawn_shop_a01\'s crates stood on that route at 0.263.0). The\n  shelter pass stood one piece, night_pawn\'s safe room\'s tall crate, where the refurnish took the piece that had\n  sheltered it. Furnish\'s pieces 8,154 -> 8,139 in 23 rooms of 14 specs, every one under the walker\'s 12 % band\n  before and after; the offices 5.7 -> 4.8 % of their floor. Four hold a marker: landmark_hall_a01\'s artifact_room\n  (6 -> 3 pieces), night_pawn\'s safe_room (3 -> 1), rowhouse_raid\'s basement_vault and twin_a01\'s front_right_1 (no\n  count moved). twin_a01\'s 38 m2 front_left_0 leaves the refurnish no wall for its cigarette machine (the library\'s 86\n  -> 85).\n- **The route census**, both libraries in one session: detours over 10 % 23 -> 23 pairs, closed 0 -> 0 to a body and\n  5 -> 5 to the bake, narrowed from two abreast to single file 142 -> 141.\n- **A seeded desk still gets no chair** -- furnish seats its own hosts only -- and in an office the seeded lattice\n  takes the floor furnish stood its own desks on. Roadmap 300\'s next step lays floor hosts and seats a seeded one.\n\n### Refuted and kept\n- **A line alone, cleared as squares.** The first draft stood every room\'s pieces in one line, each cleared as the\n  square of its longest side: deli_a03\'s four want 10.5 m of clear line with the corridor between them and the strip\n  beside its stairwell is shorter, so the room the walker named kept its scatter. Two rows of two fit.\n- **Every line before choosing**, which ran `test_door_width`\'s preset test past half an hour where 0.263.0 takes 35 s\n  (the first fit wins now: 59 s; presets are not in a cold run).\n- **The line\'s own pieces set aside while clearing each**: 2.2 m between centres put 0.6 m between a counter\'s end and\n  a planter\'s, a line a body could not pass through, and `test_seed_corridor` refused it.\n- **Routes asked with the room\'s pieces standing**: they bent round where the pieces stood, and the migration lined\n  pawn_shop_a01\'s two crates onto its safe room\'s true route.\n- **Kinds alternating along a row**: a desk, a cabinet, a desk, a cabinet mid-floor.\n\n### Tests\n- `test_seed_lines.py` (new): a bare room\'s pieces are seeded in a line, a body passing between any two; `_line_up`\n  moves the same pieces and nothing else; where one line cannot, two rows do; a room nothing fits keeps its pieces;\n  THE TEST THAT MATTERS -- every library room storing a seeded piece stands it on a lattice but the two named, and\n  the library is a fixed point of the migration. On 0.263.0 the five fail, the first on behaviour.\n- `test_arrangement.py` (new): the census\'s controls -- each reason read as built, a scatter told from a row.\n- `test_marker_room_routes.py`: a room with no spot off its routes keeps its shelter, the route now covering the\n  room\'s depth -- through the one spot the square once left, by the crate\'s footprint the room has a second.\n- `test_club_fixtures.py`: the library\'s cigarette machines 86 -> 85, and why. `test_seed_corridor.py`: by footprint.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.263.0', 'Deli Counter 0.264.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
